{
  global:
    Java_*;        # all JNI functions resolved by name
    # No JNI_OnLoad/JNI_OnUnload here, unlike jni/exports.map: this library
    # defines neither, and ld.lld fails a version script that names a symbol
    # that does not exist. A wildcard that matches nothing is fine.
  local:
    *;             # hide everything else (Qt, toml++, purple-core, ...)
};
